    public BigDecimal getFloor() {
        return floorOn(today);
    }

    /** The floor in force on a date, with two decimals. */
    public BigDecimal floorOn(LocalDate date) {
        return decimal(valueOn(FLOOR, date, plain(floor)));
    }

